#include <iostream>
#include <vector>
#include <string>
using namespace std;

int placeOf(const vector<int>& b) {
    int rank = 0;
    for (int i = 0; i < 8; i++) {
        int smaller = 0;
        for (int j = i + 1; j < 8; j++) if (b[j] < b[i]) smaller++;
        rank = rank * (8 - i) + smaller;
    }
    return rank;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
    vector<vector<long long>> boards(q, vector<long long>(8));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 8; j++) {
            cin >> boards[i][j];
        }
    }

    vector<vector<int>> near = {{1, 4}, {0, 2, 5}, {1, 3, 6}, {2, 7}, {0, 5}, {1, 4, 6}, {2, 5, 7}, {3, 6}};
    vector<int> dist(40320, -1);
    vector<vector<int>> queue;
    vector<int> goal = {1, 2, 3, 4, 5, 6, 7, 0};
    dist[placeOf(goal)] = 0;
    queue.push_back(goal);
    for (size_t i = 0; i < queue.size(); i++) {
        vector<int> board = queue[i];
        int z = 0;
        while (board[z] != 0) z++;
        for (int t : near[z]) {
            vector<int> nb = board;
            swap(nb[z], nb[t]);
            int id = placeOf(nb);
            if (dist[id] < 0) {
                dist[id] = dist[placeOf(board)] + 1;
                queue.push_back(nb);
            }
        }
    }
    for (const vector<long long>& row : boards) {
        vector<int> b(8);
        for (int j = 0; j < 8; j++) b[j] = (int)row[j];
        cout << dist[placeOf(b)] << "\n";
    }

    return 0;
}

