import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int placeOf(int[] b) {
        int rank = 0;
        for (int i = 0; i < 8; i++) {
            int smaller = 0;
            for (int j = i + 1; j < 8; j++) if (b[j] < b[i]) smaller++;
            rank = rank * (8 - i) + smaller;
        }
        return rank;
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[][] boards = new long[(int) q][8];
        for (int i = 0; i < boards.length; i++) {
            for (int j = 0; j < boards[i].length; j++) {
                boards[i][j] = Long.parseLong(next());
            }
        }

        int[][] near = {{1, 4}, {0, 2, 5}, {1, 3, 6}, {2, 7}, {0, 5}, {1, 4, 6}, {2, 5, 7}, {3, 6}};
        int[] dist = new int[40320];
        Arrays.fill(dist, -1);
        int[][] queue = new int[20161][];
        int head = 0, tail = 0;
        int[] goal = {1, 2, 3, 4, 5, 6, 7, 0};
        dist[placeOf(goal)] = 0;
        queue[tail++] = goal;
        while (head < tail) {
            int[] board = queue[head++];
            int z = 0;
            while (board[z] != 0) z++;
            int here = dist[placeOf(board)];
            for (int t : near[z]) {
                int[] nb = board.clone();
                nb[z] = nb[t];
                nb[t] = 0;
                int id = placeOf(nb);
                if (dist[id] < 0) {
                    dist[id] = here + 1;
                    queue[tail++] = nb;
                }
            }
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < boards.length; i++) {
            int[] b = new int[8];
            for (int j = 0; j < 8; j++) b[j] = (int) boards[i][j];
            out.append(dist[placeOf(b)]).append("\n");
        }
        System.out.print(out);
    }
}
